from fastapi import FastAPI
from fastapi.testclient import TestClient
from pydantic import BaseModel, computed_field
import json

def test_computed_fields_separate_input_output_schemas():
    class Item(BaseModel):
        name: str

        @computed_field
        @property
        def name_upper(self) -> str:
            return self.name.upper()

    # Test with separate_input_output_schemas=True (default)
    app_true = FastAPI(separate_input_output_schemas=True)
    @app_true.get("/item", response_model=Item)
    def read_item():
        return Item(name="test")

    client_true = TestClient(app_true)
    res_true = client_true.get("/openapi.json").json()

    # Test with separate_input_output_schemas=False
    app_false = FastAPI(separate_input_output_schemas=False)
    @app_false.get("/item", response_model=Item)
    def read_item_false():
        return Item(name="test")

    client_false = TestClient(app_false)
    res_false = client_false.get("/openapi.json").json()

    # Find the schema for Item
    # With separate_input_output_schemas=True, it should be Item-Output
    # With separate_input_output_schemas=False, it should be Item

    schema_true = res_true["components"]["schemas"].get("Item-Output")
    schema_false = res_false["components"]["schemas"].get("Item")

    assert schema_true is not None, "Item-Output schema not found for separate_input_output_schemas=True"
    assert schema_false is not None, "Item schema not found for separate_input_output_schemas=False"

    # Both should have 'name' and 'name_upper'
    assert "name" in schema_true["properties"]
    assert "name_upper" in schema_true["properties"], "computed field missing in separate_input_output_schemas=True"

    assert "name" in schema_false["properties"]
    assert "name_upper" in schema_false["properties"], "computed field missing in separate_input_output_schemas=False"

if __name__ == "__main__":
    test_computed_fields_separate_input_output_schemas()
    print("Test passed!")

